import hashlib
import json
import os
from pathlib import Path
import shutil
import signal
import subprocess
import time

root = Path('/workspace/HarbiChess')
work = Path('/workspace/work/harbichess')
training = root / 'artifacts/ufuk-broad-capacity-training-controller-20261004'
checked = root / 'artifacts/ufuk-broad-capacity-posttraining-checks-20261004'
output = root / 'artifacts/ufuk-broad-capacity-strength-controller-20261004'
output.mkdir(exist_ok=False)
def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()
registered = json.loads((root / 'docs/runs/UFUK-broad-capacity-verification-controls-20261004.json').read_text())
for f in registered['files']:
    assert digest(work / Path(f['path']).name) == f['sha256']
phases = []
def descendants(pid):
    found = [pid]
    try:
        children = Path(f'/proc/{pid}/task/{pid}/children').read_text().split()
    except FileNotFoundError:
        return found
    for child in children:
        found.extend(descendants(int(child)))
    return found
def terminate_owned_tree(process):
    groups = set()
    for pid in descendants(process.pid):
        try:
            group = os.getpgid(pid)
            assert group != os.getpgrp()
            groups.add(group)
        except ProcessLookupError:
            pass
    for group in groups:
        try:
            os.killpg(group, signal.SIGTERM)
        except ProcessLookupError:
            pass
    try:
        process.wait(timeout=5)
    except subprocess.TimeoutExpired:
        pass
    for group in groups:
        try:
            os.killpg(group, signal.SIGKILL)
        except ProcessLookupError:
            pass
    process.wait()
def phase(name, script, ceiling):
    start = time.perf_counter()
    pin = work / 'broad-arena-pinned'
    command = [str(root / '.venv/bin/python'), str(work / script)]
    receipt = {'command': command, 'cwd': str(pin), 'source_commit': '70c612572e03f562f21469e546823244083a3b4a', 'script_sha256': digest(work / script), 'whole_wall_ceiling_seconds': ceiling, 'started_epoch': time.time()}
    failure = None
    with (output / (name + '.stdout.log')).open('x') as out, (output / (name + '.stderr.log')).open('x') as err:
        process = subprocess.Popen(command, cwd=pin, env={**os.environ, 'PYTHONPATH': str(pin / 'src')}, stdout=out, stderr=err, start_new_session=True)
        while process.poll() is None:
            elapsed = time.perf_counter() - start
            (output / 'progress.json').write_text(json.dumps({'status': 'running', 'phase': name, 'pid': process.pid, 'elapsed_seconds': elapsed}) + '\n')
            if elapsed >= ceiling or int(Path('/sys/fs/cgroup/memory.current').read_text()) > 15 * 1024**3 or shutil.disk_usage(root).free < 8 * 1024**3:
                failure = 'supervisor whole-wall/memory/disk ceiling; inner arm limits unchanged'
                terminate_owned_tree(process)
                break
            time.sleep(2)
    elapsed = time.perf_counter() - start
    if elapsed >= ceiling and failure is None:
        failure = 'supervisor whole clock exceeded'
    receipt.update({'returncode': process.returncode, 'failure': failure, 'whole_wall_seconds': elapsed, 'finished_epoch': time.time()})
    (output / (name + '-receipt.json')).write_text(json.dumps(receipt, indent=2) + '\n')
    phases.append(receipt)
    if failure or process.returncode:
        raise RuntimeError('failed/incomplete phase: ' + name)
try:
    deadline = json.loads((training / 'profile.json').read_text())['started_epoch'] + 32960
    while True:
        try:
            result = json.loads((checked / 'result.json').read_text())
            break
        except (FileNotFoundError, json.JSONDecodeError):
            if time.time() >= deadline:
                raise TimeoutError('registered training/native/audit aggregate plus200overhead exhausted, no extension')
            (output / 'progress.json').write_text(json.dumps({'status': 'awaiting-both-learning-seeds-and-complete-integrity', 'deadline_epoch': deadline}) + '\n')
            time.sleep(5)
    if result['status'] == 'failed-learning-no-games':
        final = {'status': 'not-run-because-registered-learning-gates-failed', 'phases': [], 'source_check_sha256': digest(checked / 'result.json'), 'scope': 'No games, alternative seed/checkpoint, promotion or extra training.'}
    else:
        assert result['status'] == 'completed-checks-awaiting-arena'
        gates = json.loads((training / 'learning-gates.json').read_text())
        assert gates['both_seeds_passed'] and gates['primary_seed'] == 20261030
        phase('five-registered-arms', 'run-ufuk-broad-capacity-strength-arena.py', 18100)
        phase('independent-speed-and-game-audit', 'run-ufuk-broad-capacity-postarena-checks.py', 700)
        post = root / 'artifacts/ufuk-broad-capacity-postarena-checks-20261004/result.json'
        checked_games = json.loads(post.read_text())
        final = {'status': checked_games['status'], 'phases': phases, 'postarena_result_sha256': digest(post), 'scope': 'Only fixed primaryseed30/five96game suite and full speed/actual legal audit. No automatic promotion, self-learning/generalElo/Stockfish-level/novelty claim.'}
except Exception as e:
    final = {'status': 'failed-or-incomplete-no-promotion', 'phases': phases, 'error': repr(e)}
    (output / 'result.json').write_text(json.dumps(final, indent=2) + '\n')
    raise
(output / 'result.json').write_text(json.dumps(final, indent=2) + '\n')
print(json.dumps(final), flush=True)
